def minimumMoves(arr):
    n = len(arr)
    dp = [[0]*n for _ in range(n)]
    for l in range(1, n+1):  # subarray length
        for i in range(n - l + 1):
            j = i + l - 1
            if i == j:
                dp[i][j] = 1
            elif arr[i] == arr[j]:
                if i + 1 > j - 1:
                    dp[i][j] = 1  # e.g. [1, 2, 1]
                else:
                    dp[i][j] = dp[i + 1][j - 1]
            else:
                dp[i][j] = float('inf')
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])
    return dp[0][n - 1] if n else 0
